version: '3.9' # optional since v1.27.0
name: coinhexa_api_prod
services:
  api_server_prod:
    build:
      context: ../../
      dockerfile: ./docker/production/api_server/Dockerfile
    container_name: api_server_prod
    depends_on:
      cache_server_prod:
        condition: service_healthy
