        condition: service_healthy
    environment:
      - ACME_OCSP=true
      - DEBUG=1
      - DEFAULT_EMAIL=something@gmail.com
      - LETSENCRYPT_EMAIL=something@gmail.com
      - LETSENCRYPT_HOST=api.coinhexa.com,www.api.coinhexa.com
      - LETSENCRYPT_TEST=true
      - VIRTUAL_HOST=api.coinhexa.com,www.api.coinhexa.com
      - VIRTUAL_PORT=21347
      - VIRTUAL_PROTO=https
    env_file:
      - .env
    image: api_server_prod_image
    networks:
      - network
    restart: 'always'
    ports:
      - '21347:21347'

  cache_server_prod:
    build:
      context: ../..
      dockerfile: ./docker/production/cache_server/Dockerfile
    container_name: cache_server_prod
    env_file:
      - .env
    healthcheck:
      test:
        ['CMD-SHELL', 'redis-cli -p 23431 -a $REDIS_PASSWORD ping | grep PONG']
      interval: 5s
      timeout: 5s
      retries: 3
      start_period: 10s
    image: cache_server_prod_image
    networks:
      - network
    ports:
      - '23431:23431'
    restart: 'always'
    volumes:
      - cache_volume:/data

  database_server_prod:
    build:
      context: ../..
      dockerfile: ./docker/production/database_server/Dockerfile
    container_name: database_server_prod
    env_file:
      - .env
    healthcheck:
      test:
        [
          'CMD-SHELL',
          "pg_isready -d 'host=database_server_prod user=coinhexa_api_user port=26189 dbname=coinhexa_api_db'",
        ]
      interval: 5s
      timeout: 5s
      retries: 3
      start_period: 10s
    image: database_server_prod_image
    networks:
      - network
    ports:
      - '26189:26189'
    restart: 'always'
    volumes:
      - database_volume:/var/lib/postgresql/data

  nginx-proxy:
    image: nginx:alpine
    container_name: nginx-proxy
    ports:
      - '80:80'
      - '443:443'
    volumes:
      - conf:/etc/nginx/conf.d
      - vhost:/etc/nginx/vhost.d
      - html:/usr/share/nginx/html
      - certs:/etc/nginx/certs:ro
    networks:
      - network

  docker-gen:
    image: jwilder/docker-gen
    container_name: nginx-proxy-gen
    command: -notify-sighup nginx-proxy -watch /etc/docker-gen/templates/nginx.tmpl /etc/nginx/conf.d/default.conf
    volumes_from:
      - nginx-proxy
    volumes:
      - /home/ec2-user/api/docker/production/web_server/nginx.tmpl:/etc/docker-gen/templates/nginx.tmpl:ro
      - /var/run/docker.sock:/tmp/docker.sock:ro
    labels:
      - 'com.github.jrcs.letsencrypt_nginx_proxy_companion.docker_gen'
    networks:
      - network

  acme-companion:
    image: nginxproxy/acme-companion
    container_name: nginx-proxy-acme
    depends_on:
      - docker-gen
      - nginx-proxy
    volumes_from:
      - nginx-proxy
    volumes:
      - certs:/etc/nginx/certs:rw
      - acme:/etc/acme.sh
      - /var/run/docker.sock:/var/run/docker.sock:ro
    networks:
      - network

networks:
  network:
    driver: bridge

volumes:
  cache_volume:
    driver: local
  database_volume:
    driver: local
  conf:
    driver: local
  vhost:
    driver: local
  html:
    driver: local
  certs:
    driver: local
  acme:
    driver: local

